{
  "historical_analysis": "The evolution of outlier trimming and robustification within k-means and related partitioning algorithms spans nearly six decades, originating from MacQueen's foundational 1967 formulation of standard k-means and its asymptotic martingale convergence. Early k-means variants lacked robustness, rendering them highly susceptible to arbitrary noise and outliers that severely biased cluster centroid updates. To address this, Cuesta-Albertos, Gordaliza, and Matrán (1997) introduced 'impartial trimming' via trimmed k-means, establishing strong consistency and proving that optimal trimming sets correspond to unions of balls. This theoretical framework was expanded by García-Escudero et al. (2003) into exploratory graphical tools using trimmed k-variance functionals to assist in determining the number of clusters $k$ and diagnosing contamination. Simultaneously, applied domains adopted heuristic trimming: Lin et al. (2004) integrated Fisher's discriminant ratio with k-means for feature selection and outlier removal in QSAR studies, while Olukanmi and Twala (2017, 2017) proposed k-means-sharp (k-means#) by modifying the centroid update step to exclude points beyond a median-absolute-deviation (MAD) threshold. Parallel theoretical inquiries by Georgogiannis (2016) analyzed robust k-means (RKM) via Moreau envelopes, demonstrating universal breakdown vulnerabilities on arbitrary data contrasted with strong restricted robustness on well-structured datasets. Recent advancements have focused on algorithmic scalability, theoretical approximation guarantees (Grunau and Rozhoň, 2022; Agrawal et al., 2023), generalized unification frameworks (Liu et al., 2023), non-parametric probabilistic detection engines (Iannaccio and Vichi, 2026), and decentralized federated IoT architectures (Al Saleh and Azar, 2026).",
  "research_gaps": [
    {
      "gap": "Lack of data-driven, automated mechanisms for tuning multi-membership and trimming proportion parameters (such as expected outlier proportion $\\alpha$ and minimum cluster membership $s$) in continuous relaxation formulations.",
      "supporting_papers": [
        "/media/soumik/storage/MTech/ATR/agents/dataset/papers/trimmed_k_means/2021/1-s2.0-S0167865522002185-main.pdf"
      ],
      "evidence": "Dorabiala et al. (2022) state that there is currently no principled, automated approach to estimating the parameters $\\alpha$ (expected outlier percentage) and $s$ (minimum cluster memberships per point) for Robust Trimmed k-means (RTKM), requiring manual user specification.",
      "why_unresolved": "Existing alternating minimization and proximal coordinate descent schemes optimize weights and centers conditioned on fixed hyperparameters, leaving adaptive co-estimation of anomaly rates and soft-membership cardinality unaddressed."
    },
    {
      "gap": "Vulnerability of baseline trusted anchors to contamination in semi-supervised federated clustering architectures.",
      "supporting_papers": [
        "/media/soumik/storage/MTech/ATR/agents/dataset/papers/trimmed_k_means/2026/5dec532efefbe1690fbc71ccd5a1ed19aeb3.pdf"
      ],
      "evidence": "Al Saleh and Azar (2026) highlight that non-robust mean and covariance estimators under anchor contamination (when planted attack rows exceed 2-5% in the commissioning anchor) degrade recall significantly because standard sample statistics are not robust.",
      "why_unresolved": "While federated baseline k-means architectures (AF-BKM) successfully resolve merge-induced precision decay using trusted benign anchors, replacing standard estimators with robust alternatives like the Minimum Covariance Determinant (MCD) within the anchor calibration loop remains unexplored."
    }
  ],
  "hypotheses": [
    {
      "hypothesis": "Integrating a Minimum Covariance Determinant (MCD) estimator for the trusted anchor in federated k-means intrusion detection will preserve recall stability even under commissioning-anchor contamination levels exceeding 5%.",
      "rationale": "Al Saleh and Azar (2026) showed that standard mean and covariance estimators in the commissioning anchor fail when contaminated by attack rows above 2-5%. MCD estimators are known to offer high breakdown points, making them ideal replacements for securing anchor-referenced calibration.",
      "supporting_papers": [
        "/media/soumik/storage/MTech/ATR/agents/dataset/papers/trimmed_k_means/2026/5dec532efefbe1690fbc71ccd5a1ed19aeb3.pdf"
      ],
      "testable_prediction": "Under a 10% malicious contamination rate in the initial benign anchor $X_a$, an MCD-backed AF-BKM coordinator will maintain an intrusion detection recall drop of less than 2%, compared to a catastrophic recall degradation in standard sample-statistic AF-BKM.",
      "caveats": "Computing exact MCD estimators introduces heavy computational overhead, which may challenge resource-constrained coordinator nodes or slow down initialization."
    },
    {
      "hypothesis": "Formulating adaptive, data-driven updates for the outlier proportion parameter $\\alpha$ and membership threshold $s$ during alternating minimization iterations will eliminate manual tuning while preserving robust clustering performance across diverse topologies.",
      "rationale": "Dorabiala et al. (2022) noted that RTKM requires manual pre-specification of $\\alpha$ and $s$. Because pseudo-isolation scores and simplex projections dynamically reflect cluster separation during optimization, tracking the inflection points of weight distributions can guide parameter adaptation.",
      "supporting_papers": [
        "/media/soumik/storage/MTech/ATR/agents/dataset/papers/trimmed_k_means/2021/1-s2.0-S0167865522002185-main.pdf",
        "/media/soumik/storage/MTech/ATR/agents/dataset/papers/trimmed_k_means/2026/2609.08494v1.pdf"
      ],
      "testable_prediction": "An RTKM variant with dynamic $\\alpha$ and $s$ updates will achieve an F1 score within 2% of the optimal grid-searched static parameter configuration across benchmark single- and multi-membership contaminated datasets without user intervention.",
      "caveats": "Dynamic updating heuristics may introduce numerical instability or premature convergence to trivial trimming solutions during early iterations when cluster centers are unstable."
    }
  ]
}

